    <link rel="stylesheet" href="https://cdn.datatables.net/2.3.2/css/dataTables.dataTables.min.css"><script src="https://cdn.datatables.net/2.3.2/js/dataTables.min.js"></script>
    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const element = document.querySelector('#vehicles-table'); const filters = ['warehouse', 'group', 'type', 'status'].map((name) => document.querySelector(`#vehicle-${name}-filter`)); const url = @json(route('vehicles.index'));
            if (typeof window.DataTable === 'function') {
                const table = new window.DataTable(element, { processing: true, serverSide: true, pageLength: 15, lengthMenu: [15, 25, 50, 100], order: [[0, 'asc']], ajax: { url, data: (request) => { request.warehouse_code = filters[0]?.value ?? ''; request.vehicle_group = filters[1]?.value ?? ''; request.vehicle_type = filters[2]?.value ?? ''; request.status = filters[3]?.value ?? ''; } }, columns: [{data:'vehicle'}, {data:'vehicle_type'}, {data:'warehouse_code', className:'coordinate-label'}, {data:'plate_number', className:'username-label'}, {data:'status', orderable:false, searchable:false}, {data:'actions', orderable:false, searchable:false, className:'align-right'}] });
                filters.forEach((filter) => filter?.addEventListener('change', () => table.ajax.reload())); return;
            }
            const load = async () => { const params = new URLSearchParams({draw:'1', start:'0', length:'100', warehouse_code:filters[0]?.value ?? '', vehicle_group:filters[1]?.value ?? '', vehicle_type:filters[2]?.value ?? '', status:filters[3]?.value ?? ''}); const response = await fetch(`${url}?${params}`, {headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest'}}); const payload = await response.json(); const body = element.querySelector('tbody'); body.innerHTML = payload.data.length ? payload.data.map((row) => `<tr><td>${row.vehicle}</td><td>${row.vehicle_type}</td><td class="coordinate-label">${row.warehouse_code}</td><td class="username-label">${row.plate_number}</td><td>${row.status}</td><td class="align-right">${row.actions}</td></tr>`).join('') : '<tr><td colspan="6" class="empty-table">No vehicles found.</td></tr>'; }; load().catch(() => { element.querySelector('tbody').innerHTML = '<tr><td colspan="6" class="empty-table">Unable to load vehicles.</td></tr>'; }); filters.forEach((filter) => filter?.addEventListener('change', load));
        });
    </script>
